// AIR-470 / ADR 0139 Path A, representative local runtime. OFFLINE ONLY: a local Miniflare / workerd instance with LOCAL D1 and R2, no Cloudflare account, no production, no network.
//
// It runs the REAL, unchanged `stageSealedGeneration` of the built Worker bundle (`dist/server/index.js`, generated by `npm run build` from `src/worker.js`, which is never edited) inside
// workerd, over a baseline made by `scripts/epg-path-a-feasibility.mjs build` (sanitized synthetic, H2a scale). The bundle is copied to a scratch directory and only an extra fetch
// route is appended to the COPY, so the seal runs in the bundle's own module scope with its real modules (`DiscoveryAuthority`, `PublishedEpg`, the planner) and the real bindings API.
//
//   npm run build
//   node scripts/epg-path-a-feasibility.mjs build --dir /tmp/<new-empty-dir> --item-bytes 700
//   node scripts/epg-path-a-workerd.mjs measure --baseline /tmp/<that-dir> [--departures 2000 --returns 200]
//
// What is and is not measured. workerd runs the same V8 as Cloudflare production, but a local workerd does not enforce the 128 MB isolate limit and its accounting is the host process: the
// tool samples the RSS and the high-water RSS of the workerd child process from /proc while the seal runs and reports the increase over the idle, warmed-up process. Host-process RSS is not
// a bound on isolate memory: it combines Miniflare/workerd, the local D1 and R2 emulation and proxy runtime allocations, and it is not Cloudflare's number.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {Miniflare,convertV4MiniflareOptions} from 'miniflare';

const SELF=fileURLToPath(import.meta.url),REPO=path.resolve(path.dirname(SELF),'..');
const MIB=1024*1024,mib=n=>Math.round(n/MIB*10)/10;
const RUN=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0');

// The extra route, appended to a COPY of the bundle. It is the unconstrained-harness `child` of the Node tool, in the bundle's own scope.
const ROUTE=`
async function __pathAMeasure(request,env){
 const url=new URL(request.url),departures=Number(url.searchParams.get('departures')||2000),returns=Number(url.searchParams.get('returns')||200);
 const base=JSON.parse(await (await env.BUCKET.get('harness/baseline.json')).text());
 const lines=async function*(key){
  const object=await env.BUCKET.get(key),reader=object.body.pipeThrough(new TextDecoderStream()).getReader();
  let tail='';
  for(;;){const step=await reader.read();if(step.done)break;const parts=(tail+step.value).split('\\n');tail=parts.pop();for(const part of parts)if(part)yield part;}
  if(tail)yield tail;
 };
 const everyN=Math.max(1,Math.floor(base.activeItems/Math.max(1,departures)));
 let scan=[],departed=0,index=0,returned=0;
 for await(const line of lines('harness/scan.ndjson')){const item=JSON.parse(line);if(departed<departures&&index%everyN===0){departed++;index++;continue;}index++;scan.push(item);}
 for await(const line of lines('harness/returns.ndjson')){if(returned>=returns)break;scan.push(JSON.parse(line));returned++;}
 const loaded=scan.length,id=${JSON.stringify(RUN(3))},at=new Date(Date.UTC(2026,9,21,12)).toISOString();
 await env.BUCKET.put('sync.json',JSON.stringify({runId:id,stage:'epg',startedAt:at,updatedAt:at}));
 await env.DB.prepare('UPDATE discovery_lease SET expires_at=1 WHERE id=1').run();
 const pointer=await env.BUCKET.head('epg/published-generation.json');
 const run={runId:id,stage:'epg',startedAt:at,watchlist:[],events:[]};
 const started=Date.now();
 let sealError=null;
 try{await stageSealedGeneration(env,run,{holder:{discovery:scan},meta:{programmeRunId:id,updatedAt:at},pending:{'programme.json':{runId:id,updatedAt:at},'discovered-films.json':{}},nextWatchlist:{updatedAt:at,films:[]},uncertain:[],publication:{programmeRunId:base.programmeRunId,phase:'published',fence:pointer.etag}});}catch(error){sealError=String(error&&error.stack||error).slice(0,600);}
 scan=null;
 return new Response(JSON.stringify({loaded,departed,returned,activeBefore:base.activeItems,stageMs:Date.now()-started,sealError,memory:typeof process!=='undefined'&&process.memoryUsage?process.memoryUsage():null}),{headers:{'content-type':'application/json'}});
}
`;
function harnessScript(){
 const bundle=path.join(REPO,'dist/server/index.js');
 assert.ok(fs.existsSync(bundle),'run `npm run build` first');
 const text=fs.readFileSync(bundle,'utf8');
 assert.ok(text.includes('\nexport default {'),'the bundle has the expected default export');
 const renamed=text.replace('\nexport default {','\nconst __workerDefault={');
 const entry='\nexport default {\n async fetch(request,env,execution){const path=new URL(request.url).pathname;if(path===\'/__ping\')return new Response(\'ok\');if(path===\'/__path-a\')return __pathAMeasure(request,env);return __workerDefault.fetch(request,env,execution);},\n async scheduled(controller,env,execution){return __workerDefault.scheduled(controller,env,execution);},\n};\n';
 return renamed+ROUTE+entry;
}

const rssOf=pid=>{try{const status=fs.readFileSync('/proc/'+pid+'/status','utf8');const get=name=>Number((status.match(new RegExp(name+':\\s+(\\d+) kB'))||[])[1]||0)*1024;return {rss:get('VmRSS'),hwm:get('VmHWM')};}catch{return null;}};
const workerdPids=()=>{const r=spawnSync('pgrep',['-P',String(process.pid)],{encoding:'utf8'});const direct=r.stdout.split('\n').filter(Boolean);const all=[...direct];for(const pid of direct){const c=spawnSync('pgrep',['-P',pid],{encoding:'utf8'});all.push(...c.stdout.split('\n').filter(Boolean));}return all.filter(pid=>{try{return /workerd/.test(fs.readFileSync('/proc/'+pid+'/cmdline','utf8'));}catch{return false;}});};

function sqliteRows(file,sql){const r=spawnSync('sqlite3',['-json',file,sql],{encoding:'utf8',maxBuffer:1<<26});assert.equal(r.status,0,r.stderr);return r.stdout.trim()?JSON.parse(r.stdout):[];}
// The persisted local R2 is read back by this unconstrained process after the runtime has stopped (a 50 MB object through the proxy worker would itself hit its limit).
function verifyFromDisk(persist,answer){
 const dir=path.join(persist,'r2','miniflare-R2BucketObject'),meta=path.join(dir,fs.readdirSync(dir).find(n=>/^[0-9a-f]{64}\.sqlite$/.test(n)));
 const blobRoot=path.join(dir,'..','path-a-bucket','blobs');
 const read=key=>{
  const row=sqliteRows(meta,"SELECT blob_id FROM _mf_objects WHERE key='"+key.replace(/'/g,"''")+"'")[0];
  assert.ok(row,'object '+key);
  const candidates=[path.join(blobRoot,row.blob_id)];
  const file=candidates.find(fs.existsSync);assert.ok(file,'blob of '+key);
  return JSON.parse(fs.readFileSync(file,'utf8'));
 };
 const doc=read('epg/generations/'+RUN(3)+'/discovery-latest.json'),pointer=read('epg/discovery-archive/v1/current.json');
 const manifest=read('epg/discovery-archive/v1/manifests/'+pointer.manifestId+'.json');
 const expected=answer.activeBefore-answer.departed+answer.returned;
 return {expectedItems:expected,scanItems:answer.loaded,ledgerItemsAfter:doc.items.length,upsertedKeys:(manifest.upsertedKeys||[]).length,departures:answer.departed,archiveItemsAfter:manifest.totals.items,
  exact:answer.loaded===expected&&doc.items.length===expected&&(manifest.upsertedKeys||[]).length===answer.departed};
}

export async function measure({baseline,departures,returns}){
 const meta=JSON.parse(fs.readFileSync(path.join(baseline,'baseline.json'),'utf8'));
 const work=fs.mkdtempSync(path.join(os.tmpdir(),'iptv-path-a-workerd-'));
 const script=path.join(work,'harness.mjs');
 fs.writeFileSync(script,harnessScript());
 const persist=path.join(work,'persist');
 const make=()=>new Miniflare(Object.assign(convertV4MiniflareOptions({
  modules:true,scriptPath:script,modulesRoot:work,compatibilityDate:'2026-10-18',compatibilityFlags:['nodejs_compat'],
  d1Databases:{DB:'path-a-db'},r2Buckets:{BUCKET:'path-a-bucket'},
  bindings:{DISCOVERY_LEDGER_MODE:'bounded'},
 }),{resourcePersistencePath:persist}));
 // 1. let Miniflare create its local D1 file, then replace it with the baseline database (a plain sqlite file of the same schema and the published ledger).
 let mf=make();
 await (await mf.getD1Database('DB')).prepare('SELECT 1').first();
 await mf.dispose();
 const d1Dir=path.join(persist,'d1','miniflare-D1DatabaseObject'),files=[];
 const walk=dir=>{for(const entry of fs.readdirSync(dir,{withFileTypes:true})){const full=path.join(dir,entry.name);if(entry.isDirectory())walk(full);else if(/^[0-9a-f]{64}\.sqlite$/.test(entry.name))files.push(full);}};
 if(fs.existsSync(d1Dir))walk(d1Dir);
 assert.equal(files.length,1,'exactly one local D1 file: '+files.join(','));
 fs.copyFileSync(path.join(baseline,'d1.sqlite'),files[0]);
 for(const sidecar of ['-wal','-shm'])fs.rmSync(files[0]+sidecar,{force:true});
 // 2. seed the local R2 with the baseline objects, the scan and the returns pool, and the published-generation pointer.
 mf=make();
 const bucket=await mf.getR2Bucket('BUCKET'),r2=path.join(baseline,'r2');
 let seeded=0;
 for(const name of fs.readdirSync(r2)){if(name.endsWith('.part'))continue;await bucket.put(decodeURIComponent(name),fs.readFileSync(path.join(r2,name)));seeded++;}
 await bucket.put('epg/published-generation.json',JSON.stringify({phase:'published',programmeRunId:meta.programmeRunId}));
 await bucket.put('harness/scan.ndjson',fs.readFileSync(path.join(baseline,'scan.ndjson')));
 await bucket.put('harness/returns.ndjson',fs.readFileSync(path.join(baseline,'returns.ndjson')));
 await bucket.put('harness/baseline.json',fs.readFileSync(path.join(baseline,'baseline.json')));
 // 3. warm the runtime with a cheap request, take the idle RSS, then run the seal while sampling the workerd process(es).
 await (await mf.dispatchFetch('http://localhost/__ping')).text();
 const pids=workerdPids();
 const sum=()=>pids.map(pid=>rssOf(pid)).filter(Boolean).reduce((a,b)=>({rss:a.rss+b.rss,hwm:a.hwm+b.hwm}),{rss:0,hwm:0});
 const idle=sum();let peak=idle.rss;
 const timer=setInterval(()=>{peak=Math.max(peak,sum().rss);},20);
 const started=Date.now();
 let answer=null,error=null;
 try{
  const response=await mf.dispatchFetch('http://localhost/__path-a?departures='+departures+'&returns='+returns);
  const body=await response.text();
  if(response.status!==200)error={status:response.status,body:body.slice(0,400)};else answer=JSON.parse(body);
 }catch(cause){error={message:String(cause?.message||cause).slice(0,400)};}
 clearInterval(timer);
 const after=sum();
 await mf.dispose();
 // 4. the semantic check, after the runtime has stopped.
 let verified=null;
 if(answer){try{verified=verifyFromDisk(persist,answer);}catch(cause){verified={error:String(cause?.message||cause).slice(0,300)};}}
 return {command:'measure',runtime:'miniflare/workerd',departures,returns,seededObjects:seeded,workerdProcesses:pids.length,wallMs:Date.now()-started,error,answer,verified,
  rssMiB:{idle:mib(idle.rss),peakDuringSeal:mib(peak),increaseOverIdle:mib(peak-idle.rss),afterSeal:mib(after.rss),highWaterProcess:mib(after.hwm)}};
}

export function assessResult(result){
 const problems=[];
 if(!result||typeof result!=='object')return ['no result'];
 if(result.error)problems.push('request failed');
 if(!result.answer)problems.push('no answer');
 else if(result.answer.sealError)problems.push('stageSealedGeneration threw');
 if(!(result.workerdProcesses>0))problems.push('no workerd process sampled');
 if(!result.verified||result.verified.error||result.verified.exact!==true)problems.push('count invariants not verified');
 return problems;
}

export async function main(argv){
 const [command,...rest]=argv,flag=(name,fallback)=>{const i=rest.indexOf(name);return i<0?fallback:rest[i+1];};
 if(command!=='measure')throw new Error('usage: measure --baseline <dir> [--departures N --returns N]');
 const baseline=flag('--baseline');
 assert.ok(baseline&&path.isAbsolute(baseline),'--baseline must be an absolute directory made by epg-path-a-feasibility.mjs build');
 const result=await measure({baseline,departures:Number(flag('--departures',2000)),returns:Number(flag('--returns',200))});
 const problems=assessResult(result);
 console.log(JSON.stringify(problems.length?{...result,failed:problems}:result));
 return problems.length?1:0;
}
if(process.argv[1]&&path.resolve(process.argv[1])===SELF)main(process.argv.slice(2)).then(code=>process.exit(code)).catch(error=>{console.error(error);process.exit(1);});
